<script lang="ts">
  import { searchIndex } from '$lib/site/nav.js'; import Icon from './Icon.svelte';
  let {open=$bindable(false),base=''}:{open?:boolean;base?:string}=$props(); let query=$state(''); let input=$state<HTMLInputElement>();
  const rows=$derived(searchIndex.filter((x)=>!query.trim()||x.keywords.includes(query.toLowerCase())||x.title.toLowerCase().includes(query.toLowerCase())));
  $effect(()=>{if(open){query='';queueMicrotask(()=>input?.focus())}});
</script>
<svelte:window onkeydown={(e)=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();open=!open}if(e.key==='Escape')open=false;if(e.key==='/'&&!open&&(e.target as HTMLElement)?.tagName!=='INPUT'){e.preventDefault();open=true}}}/>
{#if open}<div class="bg-background/70 fixed inset-0 z-50 flex items-start justify-center px-4 pt-[12vh] backdrop-blur-sm" role="presentation" onclick={(e)=>{if(e.target===e.currentTarget)open=false}}><div role="dialog" aria-modal="true" aria-label="Search documentation" class="bg-popover w-full max-w-xl overflow-hidden rounded-lg border shadow-2xl"><div class="flex items-center gap-3 border-b px-4"><Icon name="search"/><input bind:this={input} bind:value={query} placeholder="Search guides and templates" class="h-13 w-full bg-transparent outline-none"/><kbd class="text-muted-foreground font-mono text-[11px]">esc</kbd></div><div class="max-h-96 overflow-y-auto py-2">{#each [...new Set(rows.map(x=>x.section))] as section}<p class="field-label text-muted-foreground px-4 pt-3 pb-1">{section}</p>{#each rows.filter(x=>x.section===section) as row}<button onclick={()=>{open=false;window.location.href=`${base}${row.href}`}} class="hover:bg-accent flex w-full items-baseline gap-4 border-l-2 border-transparent px-4 py-2 text-left hover:border-l-primary"><span class="w-36 shrink-0 text-sm font-medium">{row.title}</span><span class="text-muted-foreground truncate text-[13px]">{row.subtitle}</span></button>{/each}{/each}{#if !rows.length}<p class="text-muted-foreground p-10 text-center">No results.</p>{/if}</div></div></div>{/if}
